        '<p class="soft">' + esc(T('ret_p')) + '</p><p><button type="button" class="btn" data-spd-off>' + esc(T(C.off ? 'turn_on' : 'turn_off')) + '</button> <button type="button" class="btn danger" data-spd-del>' + esc(T('destroy')) + '</button></p></div>';
