    var col = function (t) { return '<table class="tbl pw-w"><tbody>' + t.lines.map(function (l) { return '<tr><td>' + esc(l[0]) + '</td><td class="n">' + m0(l[1]) + '</td></tr>'; }).join('') + '</tbody></table>'; };
