      var al = $$('[data-bwamt]', box).map(function (x) { return { id: x.getAttribute('data-id'), no: x.getAttribute('data-no'), amt: r2(Math.min(num(x.value), num(x.getAttribute('data-max')))), ref: 'agst' }; }).filter(function (a) { return a.amt > 0; });
